// localQuery.js — 瀏覽器內本地篩選＋多因子評分，取代 POST 去作者 server。
// 數據源：/norn-data/stock/stat.json（S&P 500，每日由 Oracle VM 更新）。
// 用法：import { localQueryStocks } from './localQuery'
//       const rows = await localQueryStocks(queryData)  // 回傳 server 格式嘅 array
import { withPrefix } from 'gatsby'

// arg name -> { key: stat.json key, kind: 單位換算 }
// kind: 'num' 直接比較；'pct' stat 係小數（0.02），filter 係百分比數字（2）；
//       'mln' stat 係美元，filter 係百萬美元。
// 冇數據嘅 arg 唔會出現喺呢個表，filter 時直接當 pass。
const ARG_MAP = {
  'Market Cap':   { key: 'Market Cap',  kind: 'mln' },
  'Dividend %':   { key: 'Dividend %',  kind: 'pct' },
  'ROA':          { key: 'ROA',         kind: 'pct' },
  'ROE':          { key: 'ROE',         kind: 'pct' },
  'ROI':          { key: 'ROI',         kind: 'pct' },
  'P/E':          { key: 'P/E',         kind: 'num' },
  'Forward P/E':  { key: 'Forward P/E', kind: 'num' },
  'EPS this Y':   { key: 'EPS this Y',  kind: 'pct' },
  'EPS next Y_%': { key: 'EPS next Y_%',kind: 'pct' },
  'PEG':          { key: 'PEG',         kind: 'num' },
  'P/S':          { key: 'P/S',         kind: 'num' },
  'P/B':          { key: 'P/B',         kind: 'num' },
  'P/C':          { key: 'P/C',         kind: 'num' },
  'P/FCF':        { key: 'P/FCF',       kind: 'num' },
  'Quick Ratio':  { key: 'Quick Ratio', kind: 'num' },
  'Current Ratio':{ key: 'Current Ratio',kind: 'num' },
  'Debt/Eq':      { key: 'Debt/Eq',     kind: 'num' },
  'LT Debt/Eq':   { key: 'LT Debt/Eq',  kind: 'num' },
  'Insider Trans':{ key: 'Insider Trans',kind: 'num' },
  'Inst Trans':   { key: 'Inst Trans',  kind: 'num' },
  'Gross Margin': { key: 'Gross Margin',kind: 'pct' },
  'Oper. Margin': { key: 'Oper. Margin',kind: 'pct' },
  'Profit Margin':{ key: 'Profit Margin',kind: 'pct' },
  'Short Float':  { key: 'Short Float', kind: 'pct' },
  '52W High':     { key: '52W High',    kind: 'pct' },
  '52W Low':      { key: '52W Low',     kind: 'pct' },
  'Perf Week':    { key: 'Perf Week',   kind: 'pct' },
  'Perf Month':   { key: 'Perf Month',  kind: 'pct' },
  'Perf Quarter': { key: 'Perf Quarter',kind: 'pct' },
  'Perf Half Y':  { key: 'Perf Half Y', kind: 'pct' },
  'Perf Year':    { key: 'Perf Year',   kind: 'pct' },
  'Perf YTD':     { key: 'Perf YTD',    kind: 'pct' },
  'SMA20':        { key: 'SMA20',       kind: 'pct' },
  'SMA50':        { key: 'SMA50',       kind: 'pct' },
  'SMA200':       { key: 'SMA200',      kind: 'pct' },
  'Sales Q/Q':    { key: 'Sales Q/Q',   kind: 'pct' },
  'EPS Q/Q':      { key: 'EPS Q/Q',     kind: 'pct' },
  'Recomm_RecommendationMean': { key: 'Recom', kind: 'num' },
  'Recommendation': { key: 'Recom',     kind: 'num' },
}

// multi-factor：weight name -> { get: row => 數字或 null, higherBetter: bool }
// 冇數據嘅因子唔會出現喺呢個表。
const FACTORS = {
  'E/P_w':   { get: r => num(r['P/E']) > 0 ? 1 / num(r['P/E']) : null, higherBetter: true },
  'B/P_w':   { get: r => num(r['P/B']) > 0 ? 1 / num(r['P/B']) : null, higherBetter: true },
  'S/P_w':   { get: r => num(r['P/S']) > 0 ? 1 / num(r['P/S']) : null, higherBetter: true },
  'FCF/P_w': { get: r => num(r['P/FCF']) > 0 ? 1 / num(r['P/FCF']) : null, higherBetter: true },
  'ROA_w':   { get: r => num(r['ROA']), higherBetter: true },
  'ROE_w':   { get: r => num(r['ROE']), higherBetter: true },
  'ROI_w':   { get: r => num(r['ROI']), higherBetter: true },
  'DIV_w':   { get: r => num(r['Dividend %']), higherBetter: true },
  'TgtPrice_w': { get: r => {
      const tp = num(r['Target Price']), c = num(r['Close'])
      return (tp !== null && c > 0) ? (tp - c) / c : null
    }, higherBetter: true },
  'ShortFloat_w': { get: r => num(r['Short Float']), higherBetter: false },
  'Range52W_w': { get: r => rangePosition(r), higherBetter: false },  // 愈接近52週低位愈平，低位好
}

function num(v) {
  if (v === '-' || v === null || v === undefined || v === '') return null
  const n = Number(v)
  return isNaN(n) ? null : n
}

// "139.34 - 184.90" -> (Close-Low)/(High-Low)，愈接近 1 代表愈近 52 週高位
function rangePosition(row) {
  const c = num(row['Close'])
  const s = row['52W Range']
  if (c === null || typeof s !== 'string') return null
  const m = s.split('-')
  if (m.length !== 2) return null
  const lo = Number(m[0]), hi = Number(m[1])
  if (isNaN(lo) || isNaN(hi) || hi <= lo) return null
  return (c - lo) / (hi - lo)
}

function toComparable(rowVal, kind) {
  const v = num(rowVal)
  if (v === null) return null
  if (kind === 'pct') return v * 100
  if (kind === 'mln') return v / 1e6
  return v
}

// 單一 arg 篩選：from/end 係字串，空字串 = 冇下限／上限
// 用嚴格 > / <（跟 UI label 語義）
function passArg(row, arg, universeHasData) {
  const spec = ARG_MAP[arg.name]
  if (!spec) return true  // 冇數據嘅條件，當 pass
  if (!universeHasData[arg.name]) return true  // 成個 universe 都冇數據，當 "Any"
  const from = arg.from === '' || arg.from == null ? null : Number(arg.from)
  const end = arg.end === '' || arg.end == null ? null : Number(arg.end)
  if (from === null && end === null) return true  // "Any"
  const v = toComparable(row[spec.key], spec.kind)
  if (v === null) return false  // 缺數據，當唔符合
  if (from !== null && !(v > from)) return false
  if (end !== null && !(v < end)) return false
  return true
}

function meanStd(vals) {
  const n = vals.length
  if (n === 0) return [0, 0]
  const m = vals.reduce((a, b) => a + b, 0) / n
  const sd = Math.sqrt(vals.reduce((a, b) => a + (b - m) * (b - m), 0) / n)
  return [m, sd]
}

// multi-factor 評分：每個非零 weight 嘅因子，喺已篩選 universe 做 percentile rank（0~1，最好=1），
// mf_score = 100 × Σ(weight × rank) ÷ Σ(有數據因子嘅 weight)。方向按 higherBetter 反轉。
function scoreStocks(stocks, weights) {
  const active = Object.entries(weights || {})
    .map(([name, w]) => ({ name, w: Number(w), spec: FACTORS[name] }))
    .filter(f => f.spec && !isNaN(f.w) && f.w !== 0)
  if (active.length === 0 || stocks.length <= 1) {
    const scored = stocks.map(s => ({ symbol: s.symbol, row: s.row, mf_score: 0 }))
    scored.sort((a, b) => a.symbol.localeCompare(b.symbol))
    return scored
  }
  // 每個因子：有數據嘅股票排名
  const ranks = new Map()  // symbol -> Map(factorName -> percentile)
  for (const f of active) {
    const withVal = stocks
      .map(s => ({ symbol: s.symbol, v: f.spec.get(s.row) }))
      .filter(x => x.v !== null)
    // 愈好排愈前
    withVal.sort((a, b) => f.spec.higherBetter ? b.v - a.v : a.v - b.v)
    const n = withVal.length
    withVal.forEach((x, i) => {
      const pct = n <= 1 ? 1 : (n - 1 - i) / (n - 1)  // 最好=1，最差=0
      if (!ranks.has(x.symbol)) ranks.set(x.symbol, new Map())
      ranks.get(x.symbol).set(f.name, pct)
    })
  }
  const scored = stocks.map(s => {
    let num = 0, den = 0
    for (const f of active) {
      const pct = ranks.has(s.symbol) ? ranks.get(s.symbol).get(f.name) : undefined
      if (pct === undefined) continue  // 冇數據，分子分母都唔計
      num += f.w * pct
      den += f.w
    }
    return { symbol: s.symbol, row: s.row, mf_score: den > 0 ? (100 * num) / den : 0 }
  })
  scored.sort((a, b) => b.mf_score - a.mf_score)
  return scored
}

// 主入口：input queryData（同 getCurrentSetting 格式一樣），output server 格式 array
export async function localQueryStocks(queryData) {
  const url = withPrefix('/norn-data/stock/stat.json')
  const resp = await fetch(url)
  if (!resp.ok) throw new Error('fetch stat.json failed: ' + resp.status)
  const all = await resp.json()

  let stocks = Object.entries(all).map(([symbol, row]) => ({ symbol, row }))

  // 1. 基本＋進階篩選
  const args = [...(queryData.data.baseArg || []), ...(queryData.data.advArg || [])]
  // 先計每個 arg 喺成個 universe 有冇數據（全部冇就當 "Any"，避免例如 Beta 預設 <2 令結果得 0 隻）
  const universeHasData = {}
  for (const a of args) {
    const spec = ARG_MAP[a.name]
    if (!spec) { universeHasData[a.name] = false; continue }
    universeHasData[a.name] = stocks.some(s => num(s.row[spec.key]) !== null)
  }
  stocks = stocks.filter(s => args.every(a => passArg(s.row, a, universeHasData)))

  // 2. sector/industry：stat.json 冇呢啲欄，全部 pass
  // 3. NornMinehunter tactics：tactic 分數係 server-side 計，本地冇數據，全部 pass
  //    （tactics 字串照舊傳返去結果度顯示）

  // 4. multi-factor 評分＋排序
  const weights = (queryData.data.Factor_Intersectional_v1 || {}).args || {}
  const scored = scoreStocks(stocks, weights)

  // 5. 砌 server 格式
  return scored.map(s => {
    const r = s.row
    const dash = v => (num(v) === null ? '-' : num(v))
    return {
      symbol: s.symbol,
      sector: '-1',
      industry: '-1',
      marketCap: dash(r['Market Cap']),
      PE: dash(r['P/E']),
      PB: dash(r['P/B']),
      price: dash(r['Close']),
      change: '-',       // stat.json 冇日升跌／成交量
      volume: '-',
      beneish_score: r['beneish'] === '-' ? -10000001 : num(r['beneish']),  // 缺失用 sentinel，原 mapping 會轉做 -MAX_VALUE
      risk: -1,          // risk 分數係 server-side，本地冇
      mf_score: s.mf_score,
    }
  })
}
